{
  "title": "이동 경로와 체류 및 회귀 기록",
  "cards": [
    {
      "stamp_id": "stamp:how:12081edea0846f8b",
      "title": "방향 전환을 포함한 이동",
      "text": "직선으로 이동하다가 방향을 전환하여 새로운 경로로 진입하였습니다."
    },
    {
      "stamp_id": "stamp:how:7a66b966562f7523",
      "title": "특정 구간에서의 체류",
      "text": "이동 경로상의 특정 지점에서 일정 시간 동안 머무르며 체류하였습니다."
    },
    {
      "stamp_id": "stamp:how:beaed9b87b263c05",
      "title": "이전 경로로의 회귀",
      "text": "이동을 마친 후 방향을 완전히 돌려 이전 경로를 따라 되돌아갔습니다."
    }
  ]
}
